import os
import json
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _text(value: Any) -> Optional[str]:
    if value is None:
        return None
    for attr in ("content", "value", "text"):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if isinstance(v, str):
                return v
    if isinstance(value, str):
        return value
    return str(value)


def _money_to_number(money_obj: Any) -> Optional[float]:
    if money_obj is None:
        return None
    if isinstance(money_obj, (int, float)):
        return float(money_obj)
    amount = getattr(money_obj, "amount", None)
    if amount is not None:
        try:
            return float(amount)
        except Exception:
            pass
    text = _text(money_obj)
    if text is None:
        return None
    try:
        return float(text.replace(",", "").strip())
    except Exception:
        return None


def _extract_field(fields: Dict[str, Any], *names: str) -> Any:
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    return None


def extract_invoice_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        analyze_request=document_bytes,
        content_type=content_type,
    )
    result = poller.result()

    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = doc.fields if doc and getattr(doc, "fields", None) else {}

    vendor_field = _extract_field(fields, "VendorName", "Vendor")
    date_field = _extract_field(fields, "InvoiceDate", "Date")
    total_field = _extract_field(fields, "InvoiceTotal", "Total")

    line_items: List[Dict[str, Any]] = []
    for table in getattr(result, "tables", []) or []:
        row_map: Dict[int, Dict[int, Any]] = {}
        for cell in getattr(table, "cells", []) or []:
            row = getattr(cell, "row_index", None)
            col = getattr(cell, "column_index", None)
            if row is None or col is None:
                continue
            row_map.setdefault(row, {})[col] = _text(getattr(cell, "content", None))

        if not row_map:
            continue

        header_row = row_map.get(0, {})
        headers = {col: (header_row.get(col) or "").strip().lower() for col in header_row}
        is_line_item_table = any(
            any(keyword in header for keyword in ("description", "item", "product", "qty", "quantity", "amount", "price"))
            for header in headers.values()
        )
        if not is_line_item_table:
            continue

        for row_idx in sorted(r for r in row_map.keys() if r != 0):
            row = row_map[row_idx]
            values = list(row.values())
            if not any(v and v.strip() for v in values):
                continue

            description = None
            quantity = None
            unit_price = None
            amount = None

            for col_idx, header in headers.items():
                cell_value = row.get(col_idx)
                if not cell_value:
                    continue
                h = header or ""
                if description is None and ("description" in h or "item" in h or "product" in h):
                    description = cell_value
                elif quantity is None and ("qty" in h or "quantity" in h):
                    try:
                        quantity = float(cell_value.replace(",", "").strip())
                    except Exception:
                        quantity = cell_value
                elif unit_price is None and ("unit price" in h or "price" == h or "rate" in h):
                    unit_price = _money_to_number(cell_value) if not isinstance(cell_value, (int, float)) else float(cell_value)
                elif amount is None and ("amount" in h or "total" in h):
                    amount = _money_to_number(cell_value) if not isinstance(cell_value, (int, float)) else float(cell_value)

            if description or quantity is not None or unit_price is not None or amount is not None:
                line_items.append(
                    {
                        "description": description,
                        "quantity": quantity,
                        "unit_price": unit_price,
                        "amount": amount,
                    }
                )

    vendor = _text(vendor_field)
    date = _text(date_field)
    total = _money_to_number(total_field) if total_field is not None else None

    if total is None and total_field is not None:
        total = _money_to_number(_text(getattr(total_field, "content", None)))

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }


def extract_invoice_fields_from_path(path: str, content_type: str = "application/pdf") -> Dict[str, Any]:
    with open(path, "rb") as f:
        return extract_invoice_fields(f.read(), content_type=content_type)


if __name__ == "__main__":
    import sys

    invoice_path = sys.argv[1]
    print(json.dumps(extract_invoice_fields_from_path(invoice_path), indent=2, ensure_ascii=False))
